// Atrium — starter sites. Each is a theme, header/footer, pages of section types and copy swaps (`replace`: plain
// replaceAll on the section's html, first key first). The helpers below map lists onto the library's default copy.
'use strict';

// ───────── helpers: zip new copy onto the default strings of common sections
const zip = (keys, vals) => { const o = {}; keys.forEach((k, i) => { if (vals[i] != null) o[k] = vals[i]; }); return o; };

const FAQ_KEYS = ['How does the free trial work?', 'You get every feature for 14 days, no credit card needed. At the end, pick a plan or drop to the free Starter plan — your data stays put.', 'Can I import from other tools?', 'Yes. One-click importers bring over projects, tasks and files from Trello, Asana, Jira, Notion and spreadsheets.', 'Is my data secure?', 'Data is encrypted in transit and at rest, backed up hourly and hosted in SOC 2 Type II certified data centres.', 'Do you offer discounts for nonprofits?', 'We do — registered nonprofits and schools get 50% off any paid plan. Just get in touch.', 'Can I cancel any time?', 'Of course. Cancel in two clicks from settings and you won’t be charged again. You can export everything first.'];
const faq = (title, qa, lead) => ({ ...(title ? { 'Questions, answered': title } : {}), ...(lead ? { 'Can’t find what you’re looking for? <a href="contact.html">Talk to our team</a> — we usually reply within the hour.': lead } : {}), ...zip(FAQ_KEYS, qa.flat()) });

const CARD_KEYS = ['data-icon="zap"', 'Instant everything', 'Pages load in milliseconds and sync in real time across every device your team uses.', 'data-icon="shield-check"', 'Secure by default', 'SSO, audit logs and encryption at rest. Enterprise-grade security without the paperwork.', 'data-icon="sparkles"', 'AI that helps', 'Summaries, drafts and smart suggestions that save hours — never in your way.', 'data-icon="layers"', 'Works with your stack', 'Connect 120+ tools in a click, from Slack and Google to Salesforce and GitHub.', 'data-icon="chart"', 'Insight at a glance', 'Beautiful dashboards show progress, bottlenecks and wins without a single spreadsheet.', 'data-icon="headset"', 'Humans on support', 'Real people answer in minutes, 24/7. No bots, no ticket queues, no runaround.'];
// cards(eyebrow, title, lead, [[icon, title, text] ×6])
const cards = (eyebrow, title, lead, items) => ({ '>Features</span>': `>${eyebrow}</span>`, 'Everything you need. Nothing you don’t.': title, 'Thoughtful tools that work together, so your team can focus on the work that actually matters.': lead, ...zip(CARD_KEYS, items.map(([i, t, d]) => [`data-icon="${i}"`, t, d]).flat()) });

const STAT_KEYS = ['data-count="12000" data-suffix="+">12,000+', 'teams on Northwind', 'data-count="98" data-suffix="%">98%', 'customer satisfaction', 'data-count="4" data-suffix="h">4h', 'saved per person, weekly', 'data-count="30" data-suffix="+">30+', 'countries served'];
// stats([[count, suffix, label] ×4])
const fmt = (n) => Number(n).toLocaleString('en-US');
const stats = (items) => zip(STAT_KEYS, items.map(([n, suf, l]) => [`data-count="${n}" data-suffix="${suf}">${fmt(n)}${suf}`, l]).flat());

const TESTI_KEYS = ['Testimonials', 'Teams love working this way', '“We replaced four tools with Northwind and our Monday stand-up went from an hour to ten minutes.”', 'Priya Raman', 'COO, Fieldnote', '“The first tool our designers and engineers actually agree on. It just feels right.”', 'Marcus Hale', 'Head of Product, Orbitly', '“Support answered in four minutes on a Sunday. That told me everything about this company.”', 'Sofia Alvarez', 'Founder, Greenhouse'];
// testimonials(eyebrow, title, [[quote, name, role] ×3])
const testimonials = (eyebrow, title, items) => zip(TESTI_KEYS, [eyebrow, title, ...items.map(([q, n, r]) => [`“${q}”`, n, r]).flat()]);

const TEAM_KEYS = ['Our team', 'The people behind the work', 'A small, senior team that cares deeply about every detail.', 'Ava Lindqvist', 'Founder &amp; CEO', 'Jonah Reyes', 'Head of Design', 'Noor Haddad', 'Lead Engineer', 'Leo Martin', 'Client Partner'];
