const TIER_KEYS = ['<h3>Starter</h3>', 'For individuals and side projects.', '<span class="m">$0</span><span class="y">$0</span><span class="per">/ month</span>', 'Start for free', '<li>Up to 3 members</li><li>Unlimited projects</li><li>Basic automations</li><li>Community support</li>',
  '<h3>Team</h3>', 'For growing teams that ship together.', '<span class="m">$12</span><span class="y">$10</span><span class="per">/ user / month</span>', 'Start 14-day trial', '<li>Unlimited members</li><li>AI assistant included</li><li>Advanced automations</li><li>Priority support</li>',
  '<h3>Business</h3>', 'For organisations that need control.', '<span class="m">$24</span><span class="y">$19</span><span class="per">/ user / month</span>', 'Talk to sales', '<li>SSO &amp; SCIM</li><li>Audit logs</li><li>Custom roles</li><li>Dedicated success manager</li>'];
const li = (xs) => xs.map((x) => `<li>${x}</li>`).join('');
// tiers(head, [{ name, desc, monthly, yearly, per, button, features }] ×3, toggle?)
const tiers = ({ eyebrow, title, lead, monthly, yearly, popular }, plans) => ({
  ...(eyebrow ? { '>Pricing</span>': `>${eyebrow}</span>` } : {}), 'Simple pricing that grows with you': title, 'Start free, upgrade when you’re ready. Every plan includes unlimited projects.': lead,
  ...(monthly ? { '>Monthly</button>': `>${monthly}</button>` } : {}), ...(yearly ? { 'Yearly <span class="save">Save 20%</span>': yearly } : {}), ...(popular ? { 'Most popular': popular } : {}),
  ...zip(TIER_KEYS, plans.map((p) => [`<h3>${p.name}</h3>`, p.desc, `<span class="m">${p.monthly}</span><span class="y">${p.yearly}</span><span class="per">${p.per}</span>`, p.button, li(p.features)]).flat()),
});

const FC_PRODUCT = '<nav class="col" aria-label="Product"><h4>Product</h4><a href="index.html#features">Features</a><a href="pricing.html">Pricing</a><a href="blog/index.html">Changelog</a><a href="contact.html">Book a demo</a></nav>';
