const FC_RES = '<nav class="col" aria-label="Resources"><h4>Resources</h4><a href="contact.html">Help centre</a><a href="contact.html">Community</a><a href="contact.html">Status</a><a href="contact.html">Partners</a></nav>';
const col = (title, links) => `<nav class="col" aria-label="${title}"><h4>${title}</h4>${links.map(([l, h]) => `<a href="${h}">${l}</a>`).join('')}</nav>`;
const footerCols = (a, b, c) => ({ [FC_PRODUCT]: col(...a), [FC_COMPANY]: col(...b), [FC_RES]: col(...c), 'terms.html': 'privacy.html#terms' });

const CONTACT_KEYS = ['Let’s talk', 'Questions, ideas or a project in mind? Send a note and a real person will get back to you within one business day.', 'hello@northwind.co', 'tel:+15550134000', '+1 (555) 013-4000', '<strong>Studio</strong>', '120 Market Street, Portland, OR', '<option>General question</option><option>New project</option><option>Support</option><option>Press</option>'];
const contact = ({ title, lead, email, tel, phone, placeLabel, address, subjects }) => zip(CONTACT_KEYS, [title, lead, email, tel && `tel:${tel}`, phone, placeLabel && `<strong>${placeLabel}</strong>`, address, subjects && subjects.map((s) => `<option>${s}</option>`).join('')]);

const PROSE_KEYS = ['Our story', 'Built by a small team that cares about the details', 'Northwind started in 2019 at a kitchen table, with a simple frustration: the tools we used every day made work feel harder than it needed to be. So we set out to build something calmer.', '<h3>What we believe</h3>', 'Software should get out of the way. Every feature we ship has to earn its place by saving people time or helping them think more clearly.', '<ul><li>Fewer, better features</li><li>Speed is a feature</li><li>Privacy is not optional</li></ul>', '“The best tools disappear. You only notice the work you got done.”', 'Today we are a remote team of 40 across nine countries, and we still answer support ourselves. If you have an idea or a question, we would love to hear it.'];
// prose({ eyebrow, title, p1, h3, p2, list:[…], quote, p3 }) — any part can be rich HTML
const prose = (o) => zip(PROSE_KEYS, [o.eyebrow, o.title, o.p1, o.h3 && `<h3>${o.h3}</h3>`, o.p2, o.list && `<ul>${li(o.list)}</ul>`, o.quote && `“${o.quote}”`, o.p3]);
const privacyPage = (name, email) => ({ slug: 'privacy', title: 'Privacy', nav: false, seo: { description: `How ${name} collects, uses and protects your information.` }, sections: [{ type: 'content-prose', replace: prose({ eyebrow: 'Legal', title: 'Privacy &amp; terms', p1: `This page explains what information ${name} collects when you use this website, why we collect it and the choices you have. We keep it short and in plain language.`, h3: 'What we collect', p2: 'Only what you send us through our forms (such as your name and email) and basic, anonymous analytics about how the site is used.', list: ['We never sell your information', 'We only email you if you ask us to', 'You can ask us to delete your data at any time'], quote: 'Your trust matters more to us than any metric.', p3: `<span id="terms"></span>By using this site you agree to use it lawfully. Content is provided as-is and may change. <span id="cookies"></span>We use only essential cookies and privacy-friendly analytics. Questions? Email <a href="mailto:${email}">${email}</a>.` }) }] });

